$ErrorActionPreference = 'Stop'

if (-not $env:ESPALIER_ELASTICSEARCH_URL) {
    Write-Error 'ESPALIER_ELASTICSEARCH_URL must be set'
    exit 1
}
$ElasticsearchUrl = $env:ESPALIER_ELASTICSEARCH_URL.TrimEnd('/')
$ElasticsearchAuth = $null
if ($env:ESPALIER_ELASTICSEARCH_API_KEY) {
    $ElasticsearchAuth = "ApiKey $env:ESPALIER_ELASTICSEARCH_API_KEY"
}

if (-not $env:ESPALIER_KIBANA_URL) {
    Write-Error 'ESPALIER_KIBANA_URL must be set'
    exit 1
}
