function Invoke-EsPut {
    param([string]$Path, [string]$Body)
    $headers = @{ 'Content-Type' = 'application/json' }
    if ($ElasticsearchAuth) { $headers['Authorization'] = $ElasticsearchAuth }
    try {
        Invoke-RestMethod -Method Put -Uri "$ElasticsearchUrl$Path" -Headers $headers -Body $Body | Out-Null
    } catch {
        Write-Error "PUT $Path failed: $($_.Exception.Message)"
        exit 1
    }
}

function Test-Healthy {
    try {
        $health = Invoke-RestMethod -Method Get -Uri "$ElasticsearchUrl/_cluster/health"
    } catch {
        return $false
    }
    if ($health.status -ne 'green' -and $health.status -ne 'yellow') {
        return $false
    }
    if ($KibanaUrl) {
        try {
            $status = Invoke-RestMethod -Method Get -Uri "$KibanaUrl/api/status"
        } catch {
            return $false
        }
        if ($status.status.overall.level -ne 'available') {
            return $false
        }
    }
    return $true
}

function Wait-Healthy {
    $deadline = (Get-Date).AddSeconds(30)
    while ($true) {
        if (Test-Healthy) { return }
        if ((Get-Date) -ge $deadline) {
            Write-Error 'target not healthy within 30s'
            exit 1
        }
        Start-Sleep -Milliseconds 250
    }
}

function Invoke-EsPutEmpty {
    param([string]$Path)
    $headers = @{}
    if ($ElasticsearchAuth) { $headers['Authorization'] = $ElasticsearchAuth }
    try {
        Invoke-RestMethod -Method Put -Uri "$ElasticsearchUrl$Path" -Headers $headers | Out-Null
    } catch {
        Write-Error "PUT $Path failed: $($_.Exception.Message)"
        exit 1
    }
}

function Invoke-KibanaPost {
    param([string]$Path, [string]$Body)
    $headers = @{ 'kbn-xsrf' = 'true'; 'Content-Type' = 'application/json' }
    if ($ElasticsearchAuth) { $headers['Authorization'] = $ElasticsearchAuth }
    try {
